import { computed, mount, selector, signal } from 'kerfjs';
import { Combobox } from '@kerfjs/ui/combobox';
import { wireComboboxes } from '@kerfjs/ui/wire-comboboxes';

type Source = 'incoming' | 'outgoing';
type RecordData = { id: number; label: string };

const initialRecords: RecordData[] = [
  { id: 1, label: 'One' },
  { id: 2, label: 'Two' },
  { id: 3, label: 'Three' },
  { id: 4, label: 'Four' },
];
const fruits = ['Apricot', 'Blueberry', 'Cherry'];

export function mountStudy(
  root: HTMLElement,
  onCommit: (value: string) => void,
  mark: (kind: 'row') => void,
) {
  const document = root.ownerDocument;
  const app = document.createElement('main');
  const inspector = document.createElement('div');
  const list = document.createElement('div');
  const pickerSlot = document.createElement('div');
  app.append(inspector, list, pickerSlot);
  root.append(app);

  const counts = { incoming: signal(4), outgoing: signal(7) };
  const source = signal<Source>('incoming');
  const badge = computed(() => `${counts[source.value].value} crates`);
  const selected = signal<number | null>(null);
  const selectedFor = selector(selected);
  const unmountInspector = mount(inspector, () => (
    <>
      <output data-badge="" title={badge}>{badge}</output>
      <input data-note="" aria-label="Note" />
    </>
  ));
  let disposed = false;

  function makeRow(record: RecordData) {
    const { id } = record;
    const host = document.createElement('div');
    host.style.display = 'contents';
    const label = signal(record.label);
    const isSelected = selectedFor(id);
    const ariaSelected = computed(() => String(isSelected.value));
    list.append(host);

    function renderRow() {
      mark('row');
      return (
        <div data-key={String(id)} data-row={String(id)} aria-selected={ariaSelected}>
          <span>{label}</span>
          <input aria-label={`Edit record ${id}`} />
        </div>
      );
    }

    const unmount = mount(host, renderRow);
    return {
      id,
      host,
      label,
      dispose() {
        unmount();
        host.remove();
      },
    };
  }

  let orderedRows = initialRecords.map(makeRow);

  function reorderRows(next: typeof orderedRows) {
    const active = document.activeElement;
    const focusedIndex = next.findIndex(row => row.host.contains(active));
    // Keep the focused host in place and order its siblings around it.
    let anchor = focusedIndex < 0 ? null : next[focusedIndex].host;
    const before = focusedIndex < 0 ? next.length : focusedIndex;
    for (let index = before - 1; index >= 0; index--) {
      const host = next[index].host;
      if (host.nextElementSibling !== anchor) list.insertBefore(host, anchor);
      anchor = host;
    }
    if (focusedIndex >= 0) {
      anchor = next[focusedIndex].host;
      for (let index = focusedIndex + 1; index < next.length; index++) {
        const host = next[index].host;
        if (anchor.nextElementSibling !== host) list.insertBefore(host, anchor.nextElementSibling);
        anchor = host;
      }
    }
    orderedRows = next;
  }

  function select(id: number) {
    if (!disposed) selected.value = id;
  }

  function selectFromClick(event: MouseEvent) {
    if (!(event.target instanceof Element)) return;
    const row = event.target.closest<HTMLElement>('[data-row]');
    if (row && list.contains(row)) select(Number(row.dataset.row));
  }
  list.addEventListener('click', selectFromClick);

  let releasePicker: (() => void) | undefined;

  function open() {
    if (disposed || releasePicker) return;
    const scope = document.createElement('div');
    pickerSlot.append(scope);
    let live = true;
    let reporting = false;
    let input: HTMLInputElement | null = null;

    function commit(payload: unknown) {
      if (!live || reporting) return;
      let value = payload instanceof CustomEvent ? payload.detail : payload;
      if (typeof value === 'object' && value !== null && 'value' in value) value = value.value;
      if (typeof value !== 'string') return;
      const text = value.trim();
      if (!text) return;
      reporting = true;
      queueMicrotask(() => {
        if (live && input) {
          input.value = '';
          input.dispatchEvent(new Event('input', { bubbles: true }));
        }
        reporting = false;
      });
      onCommit(text);
    }

    const props = {
      id: 'study-fruit',
      name: 'fruit',
      label: 'Fruit',
      'aria-label': 'Fruit',
      options: fruits,
      suggestions: fruits,
      allowCreate: true,
      onCommit: commit,
    };
    const unmount = mount(scope, () => (
      <Combobox {...(props as unknown as Parameters<typeof Combobox>[0])} />
    ));
    input = scope.querySelector<HTMLInputElement>('input[role="combobox"]') ?? scope.querySelector('input');
    input?.setAttribute('aria-label', 'Fruit');
    scope.addEventListener('combobox:commit', commit);
    const wire = wireComboboxes as unknown as (
      element: HTMLElement,
      options: { onCommit: typeof commit },
    ) => void | (() => void);
    const unwire = wire(scope, { onCommit: commit });
    releasePicker = () => {
      live = false;
      scope.removeEventListener('combobox:commit', commit);
      if (typeof unwire === 'function') unwire();
      unmount();
      scope.remove();
    };
  }

  function close() {
    const release = releasePicker;
    releasePicker = undefined;
    release?.();
  }

  return {
    count(which: Source, value: number) {
      if (!disposed) counts[which].value = value;
    },
    mode(which: Source) {
      if (!disposed) source.value = which;
    },
    select,
    refetch(records: RecordData[]) {
      if (disposed) return;
      const existing = new Map(orderedRows.map(row => [row.id, row] as const));
      const next = records.map(record => {
        const row = existing.get(record.id);
        if (!row) return makeRow(record);
        existing.delete(record.id);
        row.label.value = record.label;
        return row;
      });
      for (const row of existing.values()) row.dispose();
      reorderRows(next);
    },
    swap() {
      if (disposed || orderedRows.length < 2) return;
      const [first, second, ...rest] = orderedRows;
      reorderRows([second, first, ...rest]);
    },
    open,
    close,
    dispose() {
      if (disposed) return;
      disposed = true;
      close();
      list.removeEventListener('click', selectFromClick);
      for (const row of orderedRows) row.dispose();
      orderedRows = [];
      unmountInspector();
      app.remove();
    },
  };
}
